// MANUAL FILE (not generated by HARIA). Safe across regenerations.
//
// Búsqueda de un Usuario por nombre o email. La usa el login personalizado
// (Usuario.login customized, UsuarioService_Login.cs) y el LoginController de la web
// para cargar la entidad tras validar las credenciales.
using WikiGames.Domain.Entities;

namespace WikiGames.Application.Services;

public sealed partial class UsuarioService
{
    /// <summary>
    /// Busca un usuario por nombre o email. Primero coincidencia exacta; si no la hay,
    /// sin distinguir mayúsculas siempre que el resultado sea único.
    /// </summary>
    public async Task<Usuario?> FindByNombreOEmailAsync(string p_nombreOEmail)
    {
        var identificador = p_nombreOEmail?.Trim();
        if (string.IsNullOrEmpty(identificador))
        {
            return null;
        }

        var usuarios = await _repository.ReadAllAsync();

        var exacto = usuarios.FirstOrDefault(u =>
            string.Equals(u.Name, identificador, StringComparison.Ordinal)
            || string.Equals(u.Email, identificador, StringComparison.Ordinal));
        if (exacto is not null)
        {
            return exacto;
        }

        var candidatos = usuarios
            .Where(u => string.Equals(u.Name, identificador, StringComparison.OrdinalIgnoreCase)
                     || string.Equals(u.Email, identificador, StringComparison.OrdinalIgnoreCase))
            .ToList();
        return candidatos.Count == 1 ? candidatos[0] : null;
    }
}
